// Turns the live export inventory (inventory.sh) into a TypeScript file of
// type-level assertions, so tsc checks types/hull against the running hull:
// every runtime export and member is declared, nothing declared is missing at
// runtime, and every member has the right kind (function / object / primitive).
//
// usage: node drift.mjs <inventory.jsonl> <out.ts>
// A failure is a tsc error on the generated file; the comment above it names
// the module path, and the error text names the offending key.
import { readFileSync, writeFileSync } from "node:fs";

const [, , invPath, outPath] = process.argv;
const lines = readFileSync(invPath, "utf8").split("\n").filter(Boolean);
const out = [];
out.push("// GENERATED by tests/types/drift.mjs from the live hull export inventory. Do not edit.");
out.push("type Keys<T> = Exclude<keyof T, \"prototype\" | symbol>;");
out.push("type Missing<R, T> = [Exclude<R, Keys<T>>] extends [never] ? true : Exclude<R, Keys<T>>;");
out.push("type Extra<R, T> = [Exclude<Keys<T>, R>] extends [never] ? true : Exclude<Keys<T>, R>;");
out.push("type IsFn<T> = T extends (...a: never[]) => unknown ? true : T extends abstract new (...a: never[]) => unknown ? true : \"expected a function\";");
out.push("type IsObj<T> = T extends (...a: never[]) => unknown ? \"expected an object, declared a function\" : T extends object ? true : \"expected an object\";");
out.push("type IsPrim<T, P> = [T] extends [P] ? true : \"expected a primitive of the runtime's type\";");
out.push("");

const lit = (k) => JSON.stringify(k);
let n = 0;
let modules = 0;

function walk(tPath, label, node, props) {
    // props: { name: desc }; tPath: TS type expression of the container
    const names = Object.keys(props);
    const union = names.length ? names.map(lit).join(" | ") : "never";
    out.push(`// ${label}`);
    out.push(`export const m${n}: Missing<${union}, ${tPath}> = true; // ${label}: a runtime key the types lack`);
    out.push(`export const e${n}: Extra<${union}, ${tPath}> = true; // ${label}: a declared key the runtime lacks`);
    n++;
    for (const k of names) {
        const d = props[k];
        const sub = `${tPath}[${lit(k)}]`;
        const subLabel = `${label}.${k}`;
        if (d.kind === "function") {
            out.push(`export const k${n++}: IsFn<${sub}> = true; // ${subLabel}`);
            if (d.props) walk(sub, subLabel, d, d.props);
        } else if (d.kind === "object") {
            out.push(`export const k${n++}: IsObj<${sub}> = true; // ${subLabel}`);
            if (d.props) walk(sub, subLabel, d, d.props);
        } else if (d.kind === "string" || d.kind === "number" || d.kind === "boolean" || d.kind === "bigint") {
            out.push(`export const k${n++}: IsPrim<${sub}, ${d.kind}> = true; // ${subLabel}`);
        }
        // array / null / cycle / throws / undefined: the key set is checked, the shape is not
    }
}

for (const line of lines) {
    const rec = JSON.parse(line);
    const id = `M${modules++}`;
    if (rec.not_js) {
        out.push(`// ${rec.module} is not a JavaScript module: it must not be declared.`);
        out.push(`// @ts-expect-error -- ${rec.module} has no JavaScript import`);
        out.push(`import * as ${id} from ${lit(rec.module)};`);
        out.push(`export type ${id}_unused = typeof ${id};`);
        continue;
    }
    if (rec.unavailable) {
        out.push(`// ${rec.module}: not compiled into this hull; its declarations are not checked against the runtime.`);
        continue;
    }
    if (rec.module === "hull:app") {
        out.push(`import { app as ${id}_app } from "hull:app";`);
        out.push(`type ${id} = { app: typeof ${id}_app };`);
    } else {
        out.push(`import * as ${id}_ns from ${lit(rec.module)};`);
        out.push(`type ${id} = typeof ${id}_ns;`);
    }
    walk(id, rec.module, rec, rec.exports);
    out.push("");
}
writeFileSync(outPath, out.join("\n") + "\n");
console.log(`drift.mjs: ${modules} modules, ${n} assertions -> ${outPath}`);
